/* @autogenerated */
import { TestBed } from '@angular/core/testing';
import { LocalRouterService } from './local-router.service';
import { LOCAL_ROUTE_CONTEXT } from './local-route-context.token';

describe('LocalRouterService', () => {
  it('sends route to bound context', () => {
    const bind = { go: jasmine.createSpy('go') };
    TestBed.configureTestingModule({
      providers: [LocalRouterService, { provide: LOCAL_ROUTE_CONTEXT, useValue: { param: 'view', bind } }],
    });
    const service = TestBed.inject(LocalRouterService);

    service.go('list');
    expect(bind.go).toHaveBeenCalledWith({ view: 'list' });

    service.go();
    expect(bind.go).toHaveBeenCalledWith({});
  });

  it('does nothing outside a local route context', () => {
    TestBed.configureTestingModule({ providers: [LocalRouterService] });

    expect(() => TestBed.inject(LocalRouterService).go('list')).not.toThrow();
  });
});
